     5→package com.artipie.docker.proxy;
     6→
     7→import com.artipie.asto.Content;
     8→import com.artipie.asto.FailedCompletionStage;
     9→import com.artipie.asto.ext.PublisherAs;
    10→import com.artipie.docker.Digest;
    11→import com.artipie.docker.Manifests;
    12→import com.artipie.docker.Repo;
    13→import com.artipie.docker.RepoName;
    14→import com.artipie.docker.Tag;
