    16→import com.artipie.docker.http.DigestHeader;
    17→import com.artipie.docker.manifest.JsonManifest;
    18→import com.artipie.docker.manifest.Manifest;
    19→import com.artipie.docker.ref.ManifestRef;
    20→import com.artipie.http.Headers;
    21→import com.artipie.http.Slice;
    22→import com.artipie.http.rq.RequestLine;
    23→import com.artipie.http.rq.RqMethod;
    24→import com.artipie.http.rs.RsStatus;
    25→import java.util.Optional;
    26→import java.util.concurrent.CompletableFuture;
    27→import java.util.concurrent.CompletionStage;
    28→
    29→/**
    30→ * Proxy implementation of {@link Repo}.
    31→ *
    32→ * @since 0.3
    33→ * @checkstyle ClassDataAbstractionCouplingCheck (500 lines)
    34→ */
    35→public final class ProxyManifests implements Manifests {
    36→
    37→    /**
    38→     * Remote repository.
    39→     */
    40→    private final Slice remote;
    41→
    42→    /**
    43→     * Repository name.
    44→     */
    45→    private final RepoName name;
    46→
    47→    /**
    48→     * Ctor.
    49→     *
    50→     * @param remote Remote repository.
    51→     * @param name Repository name.
    52→     */
    53→    public ProxyManifests(final Slice remote, final RepoName name) {
    54→        this.remote = remote;
    55→        this.name = name;
    56→    }
    57→
    58→    @Override
    59→    public CompletionStage<Manifest> put(final ManifestRef ref, final Content content) {
    60→        throw new UnsupportedOperationException();
    61→    }
    62→
    63→    @Override
    64→    public CompletionStage<Optional<Manifest>> get(final ManifestRef ref) {
    65→        return new ResponseSink<>(
    66→            this.remote.response(
    67→                new RequestLine(RqMethod.GET, new ManifestPath(this.name, ref).string()).toString(),
    68→                Headers.EMPTY,
    69→                Content.EMPTY
    70→            ),
    71→            (status, headers, body) -> {
    72→                final CompletionStage<Optional<Manifest>> result;
    73→                if (status == RsStatus.OK) {
    74→                    final Digest digest = new DigestHeader(headers).value();
    75→                    result = new PublisherAs(body).bytes().thenApply(
    76→                        bytes -> Optional.of(new JsonManifest(digest, bytes))
    77→                    );
    78→                } else if (status == RsStatus.NOT_FOUND) {
    79→                    result = CompletableFuture.completedFuture(Optional.empty());
    80→                } else {
    81→                    result = unexpected(status);
    82→                }
    83→                return result;
    84→            }
    85→        ).result();
    86→    }
    87→
    88→    @Override
    89→    public CompletionStage<Tags> tags(final Optional<Tag> from, final int limit) {
    90→        return new ResponseSink<>(
    91→            this.remote.response(
    92→                new RequestLine(
    93→                    RqMethod.GET,
    94→                    new TagsListUri(this.name, from, limit).string()
    95→                ).toString(),
    96→                Headers.EMPTY,
    97→                Content.EMPTY
    98→            ),
    99→            (status, headers, body) -> {
   100→                final CompletionStage<Tags> result;
   101→                if (status == RsStatus.OK) {
   102→                    result = new PublisherAs(body).bytes().thenApply(
   103→                        bytes -> () -> new Content.From(bytes)
   104→                    );
   105→                } else {
   106→                    result = unexpected(status);
   107→                }
   108→                return result;
   109→            }
   110→        ).result();
   111→    }
   112→
   113→    /**
   114→     * Creates completion stage failed with unexpected status exception.
   115→     *
   116→     * @param status Status to be reported in error.
   117→     * @param <T> Completion stage result type.
   118→     * @return Failed completion stage.
   119→     */
   120→    private static <T> CompletionStage<T> unexpected(final RsStatus status) {
   121→        return new FailedCompletionStage<>(
   122→            new IllegalArgumentException(String.format("Unexpected status: %s", status))
   123→        );
   124→    }
   125→}
