    final String local = "my-test";
    this.client.run("tag", original, String.format("%s:latest", local));
    final Image img = new Image.From(
        this.repository.url(),
        local,
        tmpimg.digest(),
        tmpimg.layer()
    );
    this.client.run("tag", original, img.remote());
    return img;
}

